<?php

declare(strict_types=1);

namespace App\Support;

use App\Exceptions\FlightException;
use Symfony\Component\Yaml\Yaml;

/**
 * Writes a YAML file that Flight owns and rewrites on every run.
 */
class YamlFile
{
    /**
     * @param  array<string, mixed>  $data
     * @param  string  $note  what the reader should edit instead of this file
     */
    public static function write(string $path, array $data, string $note): void
    {
        $written = @file_put_contents(
            $path,
            "---\n".
            "# Generated by flight, do not edit. This file is overwritten on every run,\n".
            '# '.$note."\n\n".
            Yaml::dump($data, 6, 2)
        );

        if ($written === false) {
            throw FlightException::make(
                "Could not write {$path}.",
                'Check that you have permission to write there.',
            );
        }
    }
}
